Tests.EqualCheck("match repeated literal in capturing group", true, matchPattern("cat and cat", `(cat) and \1`))
Tests.EqualCheck("do not match different word with backreference", false, matchPattern("cat and dog", `(cat) and \1`))
Tests.EqualCheck("match repeated word characters", true, matchPattern("hello hello", `(\w+) \1`))
Tests.EqualCheck("do not match different words with word backreference", false, matchPattern("hello world", `(\w+) \1`))
Tests.EqualCheck("match repeated digits anchored", true, matchPattern("42 42", `^(\d+) \1$`))
Tests.EqualCheck("do not match differing digits anchored", false, matchPattern("42 43", `^(\d+) \1$`))
Tests.EqualCheck("match repeated word at ends of string", true, matchPattern("apple is apple", `^(\w+) is \1$`))
Tests.EqualCheck("do not match non-matching word at end", false, matchPattern("apple is orange", `^(\w+) is \1$`))
Tests.EqualCheck("match repeated character class group", true, matchPattern("abc-abc", `^([abc]+)-\1$`))
Tests.EqualCheck("do not match mismatched character class group", false, matchPattern("abc-def", `^([abc]+)-\1$`))
Tests.EqualCheck("match alternation inside capturing group with first branch", true, matchPattern("cat and cat", `(cat|dog) and \1`))
Tests.EqualCheck("match alternation inside capturing group with second branch", true, matchPattern("dog and dog", `(cat|dog) and \1`))
Tests.EqualCheck("do not match mixed branches in alternation group", false, matchPattern("cat and dog", `(cat|dog) and \1`))
Tests.EqualCheck("backtrack with repeating characters", true, matchPattern("aaaa", `^(\w+)\1$`))
Tests.EqualCheck("do not match odd repeating characters with equal split", false, matchPattern("aaaaa", `^(\w{2})\1$`))
Tests.EqualCheck("empty pattern matches any line", true, matchPattern("hello", ""))
